From e65f83ed0d6065e288d2b3bed29206fbd7ae49ad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:10:28 +0100
Subject: [PATCH] imports/activitymanager: move and copy windows dropped on
 activities

Dropping a task onto Move to this activity or Show also in this activity
in the Activity Manager sidebar did nothing on Wayland, as the code was
X11-only and got removed. Do it through the task model on Wayland too.

BUG: 484722
---
 imports/activitymanager/switcherbackend.cpp | 41 +++++++++++++++++++++
 imports/activitymanager/switcherbackend.h   |  6 +++
 2 files changed, 47 insertions(+)

diff --git a/imports/activitymanager/switcherbackend.cpp b/imports/activitymanager/switcherbackend.cpp
index 3744bc1fe2..d490d38449 100644
--- a/imports/activitymanager/switcherbackend.cpp
+++ b/imports/activitymanager/switcherbackend.cpp
@@ -173,6 +173,7 @@ SwitcherBackend::SwitcherBackend(QObject *parent)
     , m_shouldShowSwitcher(false)
     , m_dropModeActive(false)
     , m_runningActivitiesModel(new SortedActivitiesModel(this))
+    , m_tasksModel(new TaskManager::WindowTasksModel(this))
 {
     registerShortcut(QString::fromLatin1(s_action_name_next_activity),
                      i18n("Walk through activities"),
@@ -374,6 +375,46 @@ void SwitcherBackend::dropMove(QMimeData *mimeData, const QVariant &activityId)
 void SwitcherBackend::drop(QMimeData *mimeData, int modifiers, const QVariant &activityId)
 {
     setDropMode(false);
+
+    if (!KWindowSystem::isPlatformWayland()) {
+        return;
+    }
+
+    bool ok = false;
+    const QList<QUuid> ids = TaskManager::WaylandTasksModel::winIdsFromMimeData(mimeData, &ok);
+
+    if (!ok) {
+        return;
+    }
+
+    const QString newActivity = activityId.toString();
+    const QStringList runningActivities = m_activities.activities();
+
+    if (!runningActivities.contains(newActivity)) {
+        return;
+    }
+
+    for (int i = 0; i < m_tasksModel->rowCount(); ++i) {
+        const QModelIndex index = m_tasksModel->index(i, 0);
+        const QVariantList winIds = index.data(TaskManager::AbstractTasksModel::WinIdList).toList();
+
+        if (winIds.isEmpty() || !ids.contains(winIds.at(0).toUuid())) {
+            continue;
+        }
+
+        QStringList activities = index.data(TaskManager::AbstractTasksModel::Activities).toStringList();
+
+        if (modifiers & Qt::ControlModifier) {
+            if (!activities.contains(newActivity)) {
+                activities << newActivity;
+            }
+        } else {
+            activities.removeAll(m_activities.currentActivity());
+            activities << newActivity;
+        }
+
+        m_tasksModel->requestActivities(index, activities);
+    }
 }

 void SwitcherBackend::setDropMode(bool value)
diff --git a/imports/activitymanager/switcherbackend.h b/imports/activitymanager/switcherbackend.h
index 76900de797..2cd43272cb 100644
--- a/imports/activitymanager/switcherbackend.h
+++ b/imports/activitymanager/switcherbackend.h
@@ -30,6 +30,11 @@ class QRasterWindow;
 class QQmlEngine;
 class QJSEngine;

+namespace TaskManager
+{
+class WindowTasksModel;
+}
+
 namespace KIO
 {
 class PreviewJob;
@@ -108,4 +113,5 @@ private:
     QTimer m_dropModeHider;

     SortedActivitiesModel *m_runningActivitiesModel = nullptr;
+    TaskManager::WindowTasksModel *m_tasksModel = nullptr;
 };
